# apply-share-feature.ps1
# Run from repo root: C:\Users\T450s\Documents\logistics welcome soon page
#
# What this does:
# 1. Adds public/og-image.png — the branded share card (1200x630, dark/emerald,
#    matches the site) that WhatsApp/Instagram/iMessage show as a link preview.
# 2. Updates src/app/layout.js metadata so every share of naijadrops.tech uses
#    that image + an August 10 launch message (Open Graph + Twitter Card).
# 3. Adds src/components/ui/ShareButton.jsx — a native share button (uses the
#    phone's share sheet on Android/iOS, falls back to WhatsApp on desktop).
# 4. Wires that button into the landing page hero, right under the main CTA.

$ErrorActionPreference = "Stop"

$layoutPath = "src\app\layout.js"
$pagePath   = "src\app\page.js"
$imagePath  = "public\og-image.png"
$sharePath  = "src\components\ui\ShareButton.jsx"

foreach ($p in @($layoutPath, $pagePath)) {
    if (-not (Test-Path $p)) {
        Write-Host "ERROR: Cannot find $p — run this script from the repo root." -ForegroundColor Red
        exit 1
    }
}

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
Copy-Item $layoutPath "$layoutPath.bak_$stamp"
Copy-Item $pagePath   "$pagePath.bak_$stamp"
Write-Host "Backed up layout.js and page.js with .bak_$stamp suffix" -ForegroundColor DarkGray

function Patch-File($path, $old, $new, $label) {
    $content = [System.IO.File]::ReadAllText((Resolve-Path $path))
    $count = ([regex]::Matches($content, [regex]::Escape($old))).Count
    if ($count -eq 0) {
        Write-Host "ERROR: Expected block not found in $path ($label). File may have changed. No changes made to this file." -ForegroundColor Red
        exit 1
    }
    if ($count -gt 1) {
        Write-Host "ERROR: Expected block found $count times in $path ($label). Aborting to avoid ambiguous edit." -ForegroundColor Red
        exit 1
    }
    $updated = $content.Replace($old, $new)
    [System.IO.File]::WriteAllText((Resolve-Path $path), $updated, (New-Object System.Text.UTF8Encoding($true)))
    Write-Host "Patched $path ($label)" -ForegroundColor Green
}

# --- 1. Write the OG share image ---
if (-not (Test-Path "public")) { New-Item -ItemType Directory -Path "public" | Out-Null }
$b64 = @'

'@
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $imagePath), [System.Convert]::FromBase64String($b64))
Write-Host "Wrote $imagePath" -ForegroundColor Green

